import os
for root, dirs, files in os.walk('.'):
    for f in files:
        p = os.path.join(root, f)
        try:
            text = open(p).read()
        except Exception:
            continue
        if 'def checksum' in text:
            print(p)
            for i, line in enumerate(text.splitlines(), 1):
                if 'checksum' in line or p.endswith('lib.py'):
                    print(f"{i}: {line}")
